insert into restaurants (id, owner_id, name, description, area, address, lat, lng, phone, is_veg_only, has_ac, dine_in, takeaway, student_discount, price_per_head, vibe_tags, owner_name, restaurant_category, cuisines, delivery, outdoor_seating, parking, wifi, upi_card, wheelchair_accessible, family_friendly, opening_hours, cover_image_url, status, created_at) values
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8001-000000000001', 'Biryani Adda', 'The heavy-duty dum biryani spot every hostel argues about. Handi portions built for sharing, and a student thali on weekdays.', 'Kakatiya', 'Kakatiya University Cross, Warangal', 17.9884, 79.5941, '+91 98480 00001', false, true, true, true, true, 180, array['group', 'celebration', 'comfort']::text[], 'Biryani Adda Owner', 'Restaurant', array['Biryani', 'North Indian']::text[], true, false, true, false, true, false, true, '{"mon":[{"open":"11:30","close":"23:30"}],"tue":[{"open":"11:30","close":"23:30"}],"wed":[{"open":"11:30","close":"23:30"}],"thu":[{"open":"11:30","close":"23:30"}],"fri":[{"open":"11:30","close":"23:59"}],"sat":[{"open":"11:30","close":"23:59"}],"sun":[{"open":"12:00","close":"23:00"}]}'::jsonb, '/seed/biryani-adda.svg', 'active', '2026-05-28T05:24:30.735Z'),
  ('00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8001-000000000002', 'Momo Nation', 'Steamed, fried, tandoori and the notorious ghost-pepper momos. Quick counter service, most plates under ₹120.', 'Kakatiya', 'Excise Colony Road, Warangal', 17.9912, 79.5889, '+91 98480 00002', false, false, true, true, true, 100, array['quick', 'chill']::text[], 'Momo Nation Owner', 'Street food', array['Chinese', 'Fast Food']::text[], true, true, false, false, true, false, true, '{"mon":[{"open":"12:00","close":"22:00"}],"tue":[{"open":"12:00","close":"22:00"}],"wed":[],"thu":[{"open":"12:00","close":"22:00"}],"fri":[{"open":"12:00","close":"22:30"}],"sat":[{"open":"12:00","close":"22:30"}],"sun":[{"open":"12:00","close":"22:00"}]}'::jsonb, '/seed/momo-nation.svg', 'active', '2026-06-12T05:24:30.737Z'),
  ('00000000-0000-4000-8000-000000000003', '00000000-0000-4000-8001-000000000003', 'Chai Theory', 'Slow chai, fast wifi. Kulhad chai, maggi variations and bun maska until 2am — the unofficial night-before-exams venue.', 'Vidyaranyapuri', 'Vidyaranyapuri Main Road, Warangal', 17.9767, 79.6013, '+91 98480 00003', true, false, true, true, false, 70, array['study', 'latenight', 'chill']::text[], 'Chai Theory Owner', 'Cafe', array['Cafe', 'Beverages', 'Fast Food']::text[], false, true, false, true, true, false, true, '{"mon":[{"open":"08:00","close":"02:00"}],"tue":[{"open":"08:00","close":"02:00"}],"wed":[{"open":"08:00","close":"02:00"}],"thu":[{"open":"08:00","close":"02:00"}],"fri":[{"open":"08:00","close":"02:00"}],"sat":[{"open":"09:00","close":"02:00"}],"sun":[{"open":"09:00","close":"00:30"}]}'::jsonb, '/seed/chai-theory.svg', 'active', '2026-04-28T05:24:30.737Z'),
  ('00000000-0000-4000-8000-000000000004', '00000000-0000-4000-8001-000000000004', 'Southern Spice Tiffins', 'Ghee podi dosa, hot idli by the plate, filter coffee. Split shift: breakfast rush and a dinner reopening, closed in between.', 'Vidyaranyapuri', 'Near LB Nagar Circle, Warangal', 17.9721, 79.6078, '+91 98480 00004', true, true, true, true, true, 90, array['comfort', 'quick']::text[], 'Southern Spice Tiffins Owner', 'Restaurant', array['South Indian']::text[], true, false, true, false, true, true, true, '{"mon":[{"open":"07:00","close":"11:30"},{"open":"17:00","close":"22:00"}],"tue":[{"open":"07:00","close":"11:30"},{"open":"17:00","close":"22:00"}],"wed":[{"open":"07:00","close":"11:30"},{"open":"17:00","close":"22:00"}],"thu":[{"open":"07:00","close":"11:30"},{"open":"17:00","close":"22:00"}],"fri":[{"open":"07:00","close":"11:30"},{"open":"17:00","close":"22:00"}],"sat":[{"open":"07:00","close":"22:00"}],"sun":[{"open":"07:00","close":"14:00"}]}'::jsonb, '/seed/southern-spice.svg', 'active', '2026-06-27T05:24:30.737Z'),
  ('00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8001-000000000005', 'Scoops & Stories', 'Ice cream parlour with sundaes named after campus landmarks. Date-night booths, board games, and a brownie sizzler worth the wait.', 'Hunter Road', 'Hunter Road, Hanamkonda', 18.0102, 79.5623, '+91 98480 00005', true, true, true, true, false, 150, array['date', 'chill', 'celebration']::text[], 'Scoops & Stories Owner', 'Dessert shop', array['Desserts', 'Beverages']::text[], true, false, true, true, true, true, true, '{"mon":[{"open":"13:00","close":"23:30"}],"tue":[{"open":"13:00","close":"23:30"}],"wed":[{"open":"13:00","close":"23:30"}],"thu":[{"open":"13:00","close":"23:30"}],"fri":[{"open":"13:00","close":"00:30"}],"sat":[{"open":"12:00","close":"00:30"}],"sun":[{"open":"12:00","close":"23:30"}]}'::jsonb, '/seed/scoops-stories.svg', 'active', '2026-07-12T05:24:30.737Z'),
  ('00000000-0000-4000-8000-000000000006', '00000000-0000-4000-8001-000000000006', 'Hunter Road Grill', 'Charcoal grills, shawarma rolls and a rooftop that hosts open mics. The go-to for end-of-sem celebrations.', 'Hunter Road', 'Opp. Public Garden, Hunter Road, Hanamkonda', 18.0075, 79.5588, '+91 98480 00006', false, true, true, false, true, 350, array['group', 'celebration', 'latenight']::text[], 'Hunter Road Grill Owner', 'Restaurant', array['North Indian', 'Continental', 'Fast Food']::text[], false, true, true, true, true, false, false, '{"mon":[],"tue":[{"open":"17:00","close":"23:59"}],"wed":[{"open":"17:00","close":"23:59"}],"thu":[{"open":"17:00","close":"23:59"}],"fri":[{"open":"17:00","close":"01:00"}],"sat":[{"open":"13:00","close":"01:00"}],"sun":[{"open":"13:00","close":"23:30"}]}'::jsonb, '/seed/hunter-grill.svg', 'active', '2026-07-27T05:24:30.737Z');
