  ('00000000-0000-4000-8003-000000000005', '00000000-0000-4000-8000-000000000004', 'Filter coffee free with any dosa', 'Morning shift only, till 11:30am.', 'Free coffee', '2026-08-25T22:12:30.737Z', '2026-08-26T08:24:30.737Z', true, 0, '2026-08-25T22:12:30.737Z'),
