insert into reviews (id, booking_id, student_id, restaurant_id, rating, comment, created_at) values
  ('00000000-0000-4000-8006-000000000001', '00000000-0000-4000-8007-000000000001', '00000000-0000-4000-8008-000000000001', '00000000-0000-4000-8000-000000000001', 5, 'The mutton dum is unreal. Worth every rupee of the mess-skip.', '2026-08-16T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000002', '00000000-0000-4000-8007-000000000002', '00000000-0000-4000-8008-000000000002', '00000000-0000-4000-8000-000000000001', 4, 'Great biryani, service slows down badly on weekends.', '2026-08-20T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000003', '00000000-0000-4000-8007-000000000003', '00000000-0000-4000-8008-000000000003', '00000000-0000-4000-8000-000000000002', 4, 'Ghost pepper momos are a rite of passage. Carry water.', '2026-08-18T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000004', '00000000-0000-4000-8007-000000000004', '00000000-0000-4000-8008-000000000001', '00000000-0000-4000-8000-000000000003', 5, 'Carried our entire end-sem prep. The 2am chai hits different.', '2026-08-11T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000005', '00000000-0000-4000-8007-000000000005', '00000000-0000-4000-8008-000000000002', '00000000-0000-4000-8000-000000000004', 5, 'Podi dosa as good as home. Go before 9am or queue.', '2026-08-22T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000006', '00000000-0000-4000-8007-000000000006', '00000000-0000-4000-8008-000000000003', '00000000-0000-4000-8000-000000000005', 4, 'Cute spot, brownie sizzler is the move. Slightly pricey.', '2026-08-23T05:24:30.738Z'),
  ('00000000-0000-4000-8006-000000000007', '00000000-0000-4000-8007-000000000007', '00000000-0000-4000-8008-000000000001', '00000000-0000-4000-8000-000000000006', 5, 'Rooftop + shawarma + open mic. End-sem sorted.', '2026-08-24T05:24:30.738Z');
